import { useCallback, useEffect, useRef, useState } from "react";
import axios from "axios";
import { getAdminAuthConfig } from "../_shared/utils/admin-auth.utils";

const button = "rounded-xl bg-blue px-4 py-2 text-sm font-semibold text-white disabled:opacity-50";
const field = "w-full rounded-xl border border-darkBlue/10 bg-white px-3 py-2 text-sm";
const statusLabels = { unconfigured: "Non configuré", preparing: "Préparation", compliance_pending: "Attente de conformité", hardware_pending: "Attente du matériel", ready_for_test: "Prêt à tester", active: "Actif", incident: "Incident", suspended: "Suspendu" };
const recoveryLabels = { found: "Ressource retrouvée", absent: "Aucune ressource trouvée", partial: "Configuration SIP partielle", ambiguous: "Plusieurs ressources possibles", different: "Configuration différente", unknown: "Vérification indisponible" };
const steps = ["Informations du restaurant", "Sous-compte Twilio", "Conformité réglementaire", "Numéro de téléphone", "SIP et webhooks", "Terminal et renvoi d’appel", "Tests et activation"];
const checklistLabels = {
  terminalConnected: "Terminal connecté et vérifié",
  operatorForwarding: "Renvoi opérateur vérifié",
  incomingTest: "Appel entrant testé",
  outgoingTest: "Appel sortant testé",
  callerIdTest: "Numéro appelant vérifié",
  popupTest: "Popup Dashboard vérifiée",
  pushTest: "Notification Réservations vérifiée",
  customerTest: "Identification client vérifiée",
  emergencyTest: "Procédure d’appel d’urgence vérifiée",
  fallbackTest: "Secours Twilio testé",
  fallbackNormalCall: "Appel entrant testé avec Gusto disponible",
  fallbackBackendOutage: "Appel entrant testé pendant une panne de Gusto",
  fallbackSipRinging: "Sonnerie du terminal SIP vérifiée pendant la panne",
  fallbackBidirectionalAudio: "Audio dans les deux sens vérifié pendant la panne",
  fallbackBackendRecovery: "Retour au fonctionnement normal vérifié après redémarrage",
  fallbackHttpFailures: "Secours vérifié pour erreur HTTP, réponse invalide et absence de réponse",
  missedTest: "Appel manqué testé",
};

export default function CallSenseOnboarding({ restaurantId }) {
  const [data, setData] = useState(null);
  const [terminalType, setTerminalType] = useState("softphone");
  const [bundle, setBundle] = useState("");
  const [operator, setOperator] = useState("");
  const [accountSid, setAccountSid] = useState("");
  const [checklist, setChecklist] = useState({});
  const [numbers, setNumbers] = useState(null);
  const [quote, setQuote] = useState(null);
  const [numberSid, setNumberSid] = useState("");
  const [addresses, setAddresses] = useState(null);
  const [addressSid, setAddressSid] = useState("");
  const [domainSid, setDomainSid] = useState("");
  const [fallbackUrl, setFallbackUrl] = useState("");
  const [fallbackTemplate, setFallbackTemplate] = useState(null);
  const [credentialListSid, setCredentialListSid] = useState("");
  const [sipSecret, setSipSecret] = useState(null);
  const [sipCopyStatus, setSipCopyStatus] = useState("");
  const [resources, setResources] = useState(null);
  const [technical, setTechnical] = useState(null);
  const [automation, setAutomation] = useState(null);
  const [maxAmount, setMaxAmount] = useState("");
  const [autoCurrency, setAutoCurrency] = useState("USD");
  const [autoRunning, setAutoRunning] = useState(false);
  const [changeBudget, setChangeBudget] = useState(false);
  const [compliance, setCompliance] = useState(null);
  const [complianceChecking, setComplianceChecking] = useState(false);
  const [liveCompliance, setLiveCompliance] = useState(null);
  const [recoveryResult, setRecoveryResult] = useState(null);
  const [usage, setUsage] = useState(null);
  const [metering, setMetering] = useState(null);
  const [reconciliation, setReconciliation] = useState(null);
  const [subscriptionRecovery, setSubscriptionRecovery] = useState(null);
  const [twilioInventory, setTwilioInventory] = useState(null);
  const [twilioStart, setTwilioStart] = useState("");
  const [twilioEnd, setTwilioEnd] = useState("");
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [confirmation, setConfirmation] = useState(null);
  const [acknowledgement, setAcknowledgement] = useState("");
  const [confirmationError, setConfirmationError] = useState("");
  const [step, setStep] = useState(0);
  const actionRunning = useRef(false);
  const confirmationRunning = useRef(false);
  const confirmationTrigger = useRef(null);
  const progressQueue = useRef(Promise.resolve());
  const sipRequestEpoch = useRef(0);
  const initialized = useRef(false);
  const complianceSequence = useRef(0);
  const base = `${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense-onboarding`;
  const load = useCallback(async () => {
    const response = await axios.get(base, getAdminAuthConfig());
    setData(response.data);
    setAutomation(response.data.draft?.automation || null);
    if (!initialized.current) {
      let remembered = 0;
      try { remembered = Number(window.localStorage.getItem(`callsense-step:${restaurantId}`)) || 0; } catch (_) {}
      const persisted = response.data.draft?.wizardStep;
      setStep(Math.max(0, Math.min(6, Number.isInteger(persisted) ? persisted : remembered)));
      initialized.current = true;
    }
    setTerminalType(response.data.draft?.terminalType || "softphone");
    setBundle(response.data.draft?.regulatoryBundleSid || "");
    setOperator(response.data.draft?.operator || "");
    setChecklist(response.data.draft?.checklist || {});
    setFallbackUrl(response.data.draft?.verifiedFallbackUrl || response.data.draft?.fallbackProbeUrl || response.data.draft?.voiceFallbackUrl || "");
  }, [base, restaurantId]);
  useEffect(() => { load().catch(() => setMessage("Impossible de charger CallSense.")); }, [load]);
  useEffect(() => {
    if (!sipSecret) return;
    const timer = setTimeout(() => { setSipSecret(null); setSipCopyStatus(""); }, 60000);
    return () => clearTimeout(timer);
  }, [sipSecret]);
  useEffect(() => { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); return () => { sipRequestEpoch.current++; }; }, [restaurantId]);
  useEffect(() => {
    if (!autoRunning && automation?.status !== "running") return;
    const timer = setInterval(() => { axios.get(base, getAdminAuthConfig()).then(response => { setData(response.data); setAutomation(response.data.draft?.automation || null); setFallbackUrl(current => current || response.data.draft?.fallbackProbeUrl || ""); }).catch(() => {}); }, 2000);
    return () => clearInterval(timer);
  }, [autoRunning, automation?.status, base]);
  async function action(fn) {
    if (actionRunning.current) return false;
    actionRunning.current = true;
    setBusy(true); setMessage("");
    try { await progressQueue.current; await fn(); await load(); return true; }
    catch (err) {
      const errorMessage = err?.response?.data?.message || "Opération impossible. Vérifiez l’état avant toute reprise.";
      setMessage(errorMessage);
      setConfirmationError(errorMessage === "Numéro ou prix modifié : actualisez la recherche" ? `${errorMessage}. Aucun achat n’a été lancé.` : errorMessage.startsWith("Achat refusé par Twilio :") ? errorMessage : `${errorMessage} Une opération peut avoir été effectuée : vérifiez son état avant toute reprise.`);
      await load().catch(() => {});
      return false;
    }
    finally { actionRunning.current = false; setBusy(false); }
  }
  const requestConfirmation = (text, run, options = {}) => {
    if (actionRunning.current || confirmationRunning.current) return;
    confirmationTrigger.current = typeof document !== "undefined" ? document.activeElement : null;
    setConfirmationError(""); setAcknowledgement("");
    setConfirmation({ text, run, ...options });
  };
  const closeConfirmation = () => {
    if (confirmationRunning.current) return;
    setConfirmation(null); setConfirmationError("");
    confirmationTrigger.current?.focus?.();
  };
  const confirmAction = async () => {
    if (confirmationRunning.current || confirmationError || !confirmation || (confirmation.phrase && acknowledgement !== confirmation.phrase)) return;
    confirmationRunning.current = true;
    const succeeded = await confirmation.run(acknowledgement);
    confirmationRunning.current = false;
    if (succeeded) closeConfirmation();
  };
  const save = () => axios.put(base, { terminalType, regulatoryBundleSid: bundle.trim(), operator: operator.trim() }, getAdminAuthConfig());
  const verifyCompliance = useCallback(async (sid) => {
    const sequence = ++complianceSequence.current;
    setCompliance(null);
    if (!sid) { setComplianceChecking(false); return; }
    setComplianceChecking(true);
    try {
      const response = await axios.get(`${base}/compliance`, getAdminAuthConfig());
      if (sequence === complianceSequence.current) setCompliance(response.data.bundle?.sid === sid ? response.data.bundle : { sid, unavailable: true });
    } catch (_) { if (sequence === complianceSequence.current) setCompliance({ sid, unavailable: true }); }
    finally { if (sequence === complianceSequence.current) setComplianceChecking(false); }
  }, [base]);
  useEffect(() => {
    const sid = data?.draft?.regulatoryBundleSid;
    if (sid && data?.draft?.accountSid && !data?.liveExists) verifyCompliance(sid);
    return () => { complianceSequence.current++; };
  }, [data?.draft?.regulatoryBundleSid, data?.draft?.accountSid, data?.liveExists, verifyCompliance]);
  useEffect(() => {
    if (!data?.draft?.accountSid || data?.liveExists && !data?.liveManaged) return;
    let active = true;
    axios.get(`${base}/resources`, getAdminAuthConfig()).then((result) => { if (active) setResources(result.data); }).catch(() => { if (active) setTechnical({ status: "action_required", message: "Lecture des ressources Twilio indisponible." }); });
    return () => { active = false; };
  }, [base, data?.draft?.accountSid, data?.liveExists, data?.liveManaged]);
  const saveAndVerify = () => action(async () => {
    const sid = bundle.trim();
    complianceSequence.current++; setCompliance(null); setComplianceChecking(true);
    try { await save(); if (sid && data?.draft?.accountSid) await verifyCompliance(sid); }
    finally { setComplianceChecking(false); }
  });
  const create = () => {
    requestConfirmation("Un sous-compte Twilio sera créé pour cet établissement et associé à sa configuration CallSense. Cette opération modifie votre compte Twilio.", () => action(async () => { await save(); await axios.post(`${base}/account`, { confirm: true }, getAdminAuthConfig()); }), { title: "Créer un sous-compte Twilio", confirmLabel: "Créer le sous-compte" });
  };
  const associate = () => {
    requestConfirmation("Associer ce sous-compte Twilio à ce restaurant ? Vérifiez son identité avant de continuer.", () => action(async () => { await save(); await axios.post(`${base}/associate-account`, { accountSid: accountSid.trim(), confirm: true }, getAdminAuthConfig()); }));
  };
  const goTo = (next) => {
    if (next !== 4) { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); }
    setStep(next);
    try { window.localStorage.setItem(`callsense-step:${restaurantId}`, String(next)); } catch (_) {}
    if (!data?.liveExists || data.liveManaged) {
      progressQueue.current = progressQueue.current.catch(() => {}).then(() => axios.put(`${base}/progress`, { step: next }, getAdminAuthConfig())).catch(() => setMessage("Impossible d’enregistrer l’étape sur le serveur. Elle reste mémorisée sur cet appareil."));
    }
  };
  const runAutomation = (limit, currency, sharedCloneConsent = false, functionConsent = false) => action(async () => {
    setAutoRunning(true);
    try {
      const response = await axios.post(`${base}/automation`, { confirm: true, maxAmount: limit, currency, sharedCloneConsent, functionConsent }, getAdminAuthConfig());
      setAutomation(response.data);
      const section = { informations: 0, account: 1, compliance: 2, number: 3, technical: 4, tests: 6, recovery: 6 }[response.data.phase];
      if (section !== undefined) goTo(section);
    } finally { setAutoRunning(false); }
  });
  const draft = data?.draft;
  const config = data?.configuration;
  const legacy = Boolean(config && !data?.liveManaged);
  const legacyPoc = legacy && config.enabled && String(data?.restaurant?.name || "").trim().toLowerCase().replace(/’/g, "'") === "l'atelier des saveurs";
  const problem = (...states) => states.some((value) => value === "uncertain" || value === "pending");
  const complianceCurrent = compliance?.sid === bundle.trim() && bundle.trim() === draft?.regulatoryBundleSid ? compliance : null;
  const complianceStatus = !bundle.trim() ? "Non renseigné" : complianceChecking ? "Vérification en cours…" : !complianceCurrent || complianceCurrent.unavailable ? "Vérification impossible" : complianceCurrent.status === "twilio-approved" ? "Approuvé" : complianceCurrent.status === "twilio-rejected" ? "Refusé" : ["draft", "pending-review", "in-review"].includes(complianceCurrent.status) ? "En attente d’approbation" : "Vérification impossible";
  const stepStates = [data?.restaurant?.name ? "Disponible" : "À compléter", draft?.accountSid || config?.accountSid ? "Associé" : problem(draft?.accountOperation) ? "À vérifier" : "À configurer", complianceStatus === "Approuvé" && complianceCurrent?.compatible || liveCompliance?.verified && liveCompliance.status === "twilio-approved" ? "Approuvée" : "À vérifier", draft?.twilioNumber || config?.twilioNumber ? "Associé" : problem(draft?.numberOperation) ? "À vérifier" : "À configurer", problem(draft?.domainOperation, draft?.sipCredentialOperation, draft?.webhookOperation) ? "À vérifier" : draft?.webhookOperation === "completed" || legacy && config?.sipDomain ? "Configuré" : "À configurer", draft?.checklist?.terminalConnected ? "Test déclaré" : legacyPoc ? "POC Linphone testé" : "À tester", legacy ? config.enabled ? "Service activé" : "Service désactivé" : statusLabels[draft?.serviceStatus] || (config?.enabled ? "Service activé" : "À tester")];
  const completedSteps = [Boolean(data?.restaurant?.name), Boolean(draft?.accountSid || config?.accountSid), Boolean(complianceStatus === "Approuvé" && complianceCurrent?.compatible || liveCompliance?.verified && liveCompliance.status === "twilio-approved"), Boolean(draft?.twilioNumber || config?.twilioNumber), Boolean(draft?.webhookOperation === "completed"), Boolean(draft?.checklist?.terminalConnected && draft?.checklist?.operatorForwarding), Boolean(draft?.serviceStatus === "active")];
  const percent = Math.round(completedSteps.filter(Boolean).length * 100 / completedSteps.length);
  return <section className="p-4 text-darkBlue tablet:p-6">
    <h3 className="text-lg font-semibold">Mise en service CallSense</h3>
    <p className="mt-1 text-sm text-darkBlue/60">La préparation s’arrête lorsqu’une vérification humaine est nécessaire. Les essais et l’activation restent à confirmer.</p>
    {data && <div className="mt-4"><p className="text-sm font-semibold">Progression : {percent} %</p><progress className="mt-2 h-2 w-full accent-blue" max="100" value={percent} aria-label="Progression de la mise en service" /></div>}
    {data && !legacy && <div className="mt-4 rounded-xl border border-darkBlue/10 bg-white p-4 text-sm"><p className="font-semibold">{autoRunning || automation?.status === "running" ? "En cours" : automation?.status === "error" ? "Erreur — action nécessaire" : automation?.message ? "En attente" : "Prêt à démarrer"}</p>{automation?.message && <p className="mt-1" role="status">{automation.message}</p>}{(!automation?.maxAmount || changeBudget) && <div className="mt-3 flex flex-wrap items-end gap-2"><label>Plafond mensuel du numéro<input className={`${field} mt-1`} inputMode="decimal" value={maxAmount} onChange={e => setMaxAmount(e.target.value)} placeholder="Ex. 2.00" /></label><label>Devise<select className={`${field} mt-1`} value={autoCurrency} onChange={e => setAutoCurrency(e.target.value)}><option>USD</option><option>EUR</option></select></label></div>}<button type="button" className={`${button} mt-3`} disabled={busy || autoRunning || automation?.status === "running" || ((!automation?.maxAmount || changeBudget) && !/^(?:0|[1-9]\d{0,4})(?:\.\d{1,2})?$/.test(maxAmount))} onClick={() => automation?.maxAmount && !changeBudget && automation.functionAccepted && (data.complianceStrategy !== "shared_clone" || automation.sharedCloneAccepted) ? runAutomation(automation.maxAmount, automation.currency) : requestConfirmation(`Lancer la mise en service peut créer un sous-compte, acheter un numéro jusqu’à ${changeBudget || !automation?.maxAmount ? maxAmount : automation.maxAmount} ${changeBudget || !automation?.maxAmount ? autoCurrency : automation.currency} par mois, créer les ressources SIP, publier une Function de secours Twilio et modifier les webhooks après vérification du secours. Twilio Functions peut générer des frais liés à l’utilisation selon les tarifs de votre compte ; Gusto ne demande pas d’abonnement fixe supplémentaire pour cette fonction. ${data.complianceStrategy === "shared_clone" ? "Le dossier réglementaire Gusto approuvé sera cloné vers le sous-compte." : "Un dossier réglementaire propre devra être renseigné."}`, () => { setChangeBudget(false); return runAutomation(changeBudget || !automation?.maxAmount ? maxAmount : automation.maxAmount, changeBudget || !automation?.maxAmount ? autoCurrency : automation.currency, data.complianceStrategy === "shared_clone", true); })}>{automation?.maxAmount && !changeBudget ? "Reprendre la mise en service" : "Lancer la mise en service"}</button>{automation?.maxAmount && !changeBudget && <button type="button" className="ml-3 text-blue underline" disabled={busy} onClick={() => { setMaxAmount(automation.maxAmount); setAutoCurrency(automation.currency); setChangeBudget(true); }}>Modifier le plafond</button>}</div>}
    {data && <nav aria-label="Étapes CallSense" className="mt-5 flex flex-col gap-2">{steps.map((title, index) => <button type="button" key={title} disabled={busy} aria-current={step === index ? "step" : undefined} onClick={() => goTo(index)} className={`rounded-xl border p-3 text-left text-sm disabled:opacity-60 ${step === index ? "border-blue bg-blue/10 text-blue" : "border-darkBlue/10 bg-white"}`}><span className="font-semibold">{title}</span><span className="ml-2 text-xs">{completedSteps[index] ? "Terminé" : "En attente"} · {stepStates[index]} · Détails</span></button>)}</nav>}
    {data && <div className="mt-5 rounded-2xl border border-darkBlue/10 bg-white p-4 tablet:p-6"><p className="text-xs font-semibold text-blue">ÉTAPE {step + 1} SUR 7</p><h4 className="mt-1 text-lg font-semibold">{steps[step]}</h4></div>}
    {message && <p role="alert" className="mt-3 text-sm text-red">{message}</p>}
    {!data ? <p className="mt-3 text-sm">Chargement…</p> : <div className="mt-4 flex flex-col gap-4">
      {data.liveExists && !data.liveManaged && <div className="rounded-xl bg-blue/10 p-4 text-sm"><p className="font-semibold">Configuration persistée · {config?.enabled ? "Service activé" : "Service désactivé"}</p><p className="mt-1">État technique détaillé : {statusLabels[config?.provisioningStatus] || "non renseigné"} · Sous-compte : {config?.accountSid || "non renseigné"} · Numéro : {config?.twilioNumber || "non renseigné"}</p><p>Domaine SIP : {config?.sipDomain || "non renseigné"} · Terminal : {config?.terminalType === "softphone" ? "Softphone" : config?.terminalType || "non renseigné"}</p><p className="mt-1">Installation existante en lecture seule. {draft ? "Un dossier de préparation distinct existe." : "Aucun dossier de préparation distinct."}</p></div>}
      {legacyPoc && <div className="rounded-xl border border-blue/20 bg-white p-4 text-sm"><p className="font-semibold">Historique du POC déclaré</p><p className="mt-1">Selon les informations fournies pour L’Atelier des Saveurs, les appels entrants et l’audio dans les deux sens ont été testés avec Linphone. Ce résultat historique n’est pas une vérification automatique ni une validation de production.</p><p className="mt-1 text-darkBlue/60">Conformité Twilio : {liveCompliance?.verified ? liveCompliance.status === "twilio-approved" ? "approuvée, vérifiée auprès de Twilio" : `statut vérifié : ${liveCompliance.status || "indisponible"}` : "à vérifier"}. HT813, renvoi opérateur et scénarios de panne : non validés dans ce parcours.</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { setLiveCompliance(null); const response = await axios.get(`${base}/live-compliance`, getAdminAuthConfig()); setLiveCompliance(response.data); })}>Vérifier la conformité Twilio</button></div>}
      <div className={step === 0 ? "flex flex-col gap-4" : "hidden"}>
      <div className="text-sm"><strong>Restaurant :</strong> {data.restaurant?.name} · {data.restaurant?.phone}</div>
      <p className="text-sm">Adresse : {[data.restaurant?.address?.line1, data.restaurant?.address?.zipCode, data.restaurant?.address?.city, data.restaurant?.address?.country].filter(Boolean).join(", ") || "non renseignée"} · Contact : {data.restaurant?.email || "non renseigné"}</p>
      <p className="text-sm text-darkBlue/60">Les modifications des informations du restaurant se font dans sa fiche administrative.</p>
      </div>
      <div className={step === 5 ? "flex flex-col gap-4" : "hidden"}>
      {data.liveExists && !draft ? <p className="text-sm">Terminal de l’installation existante : {config?.terminalType === "softphone" ? "Softphone" : config?.terminalType || "non renseigné"}.</p> : <label className="text-sm">Terminal prévu<select className={`${field} mt-1`} value={terminalType} disabled={data.liveExists || busy} onChange={(e) => setTerminalType(e.target.value)}><option value="softphone">Linphone / softphone</option><option value="HT813">Grandstream HT813 — matériel à tester</option></select></label>}
      <label className="text-sm">Opérateur actuel<input className={`${field} mt-1`} value={operator} disabled={data.liveExists || busy} onChange={(e) => setOperator(e.target.value)} /></label>
      {!data.liveExists && <button type="button" className={button} disabled={busy} onClick={() => action(save)}>Enregistrer le terminal et l’opérateur</button>}
      </div>
      <div className={step === 2 ? "flex flex-col gap-4" : "hidden"}>
      {["pending", "uncertain"].includes(draft?.bundleCloneOperation) && <p role="alert" className="rounded-xl bg-orange-50 p-3 text-sm">Clonage en cours ou incertain : vérifiez les dossiers du sous-compte dans Twilio avant toute reprise. Aucun nouveau clonage ne sera lancé automatiquement.</p>}
      <label className="text-sm">Identifiant du dossier de conformité (BU...)<input className={`${field} mt-1`} value={bundle} disabled={data.liveExists || busy || complianceChecking} onChange={(e) => { complianceSequence.current++; setCompliance(null); setComplianceChecking(false); setQuote(null); setNumbers(null); setBundle(e.target.value); }} placeholder="BU…" /></label>
      <p className="text-xs text-darkBlue/60">Créez votre dossier dans Twilio → Trust Hub → Registrations → Regulatory compliance, puis renseignez son identifiant ici. Un dossier approuvé est nécessaire avant l’achat du numéro français prévu.</p>
      {!data.liveExists && <div className="flex flex-wrap gap-2"><button type="button" className={button} disabled={busy || complianceChecking} onClick={saveAndVerify}>{busy || complianceChecking ? "Vérification en cours…" : "Enregistrer et vérifier"}</button><button type="button" className="rounded-xl border border-darkBlue/10 bg-white px-4 py-2 text-sm font-semibold disabled:opacity-50" disabled={busy || complianceChecking || !draft?.accountSid || !bundle.trim() || bundle.trim() !== draft?.regulatoryBundleSid} onClick={() => verifyCompliance(bundle.trim())}>Actualiser le statut</button></div>}
      {!data.liveExists && <div role="status" className={`rounded-xl p-3 text-sm ${complianceStatus === "Approuvé" && complianceCurrent?.compatible ? "bg-green-50 text-green-800" : "bg-darkBlue/5"}`}><p className="font-semibold">{complianceStatus}</p>{complianceStatus === "Approuvé" && complianceCurrent?.compatible === false && <p>Ce dossier ne correspond pas au numéro local français prévu ; achat bloqué.</p>}{complianceStatus === "Vérification impossible" && <p>Le statut reste inconnu. Enregistrez la référence et vérifiez-la lorsque Twilio est disponible.</p>}</div>}
      </div>
      <div className={step === 1 ? "flex flex-col gap-4" : "hidden"}>
      {data.liveExists && !draft ? <p className="text-sm">Le sous-compte de la configuration persistée est affiché ci-dessus. Aucun dossier de préparation distinct.</p> :
      <div className="rounded-xl border border-darkBlue/10 p-3 text-sm">
        <p className="font-semibold">Sous-compte du dossier : {data.draft?.accountSid || (config?.accountSid ? "non renseigné dans ce dossier" : "non associé")}</p>
        <p className="mt-1 text-darkBlue/60">État : {data.draft?.accountOperation || "non commencé"}</p>
        {["pending", "uncertain"].includes(data.draft?.accountOperation) && <p className="mt-2 text-red">Création en cours ou résultat incertain. Vérifiez les sous-comptes dans Twilio avant toute reprise ; ne relancez pas la création.</p>}
        {!data.liveExists && !data.draft?.accountSid && <div className="mt-3 flex flex-col gap-2">
          <button type="button" className={button} disabled={busy || ["pending", "uncertain"].includes(data.draft?.accountOperation)} onClick={create}>Créer un sous-compte</button>
          <input className={field} value={accountSid} onChange={(e) => setAccountSid(e.target.value)} placeholder="Account SID d’un sous-compte existant" />
          <button type="button" className={button} disabled={busy || !accountSid || data.draft?.accountOperation === "pending"} onClick={associate}>Associer ce sous-compte</button>
        </div>}
      </div>}
      </div>
      <div className={step === 3 ? "flex flex-col gap-4" : "hidden"}>
      {data.draft?.accountSid && !data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm">
        <p className="font-semibold">Numéro : {data.draft.twilioNumber || "non associé"}</p><p>État : {data.draft.numberOperation || "non commencé"}</p>
        {["pending", "uncertain"].includes(data.draft.numberOperation) && <p className="mt-2 text-red">Achat en cours ou incertain pour {data.draft.pendingNumber} : vérifiez Twilio avant de continuer. Aucun achat ne sera relancé automatiquement.</p>}
        {!data.draft.phoneNumberSid && <><input className={`${field} mt-2`} value={numberSid} onChange={(e) => setNumberSid(e.target.value)} placeholder="Phone Number SID d’un numéro existant" /><button type="button" className={`${button} mt-2`} disabled={busy || !numberSid} onClick={() => { requestConfirmation("Associer ce numéro existant à ce restaurant ?", () =>  action(() => axios.post(`${base}/number-associate`, { sid: numberSid.trim(), confirm: true }, getAdminAuthConfig()))); }}>Associer le numéro</button></>}
        <div className="mt-3"><button type="button" className={button} disabled={busy} onClick={() => action(async () => { const [response, addressResult] = await Promise.all([axios.get(`${base}/number-quote`, getAdminAuthConfig()), axios.get(`${base}/addresses`, getAdminAuthConfig()).catch(() => null)]); setQuote(response.data); setNumbers(response.data.numbers); setAddresses(addressResult?.data?.addresses || null); setAddressSid(""); })}>Rechercher des numéros et tarifs</button></div>
        {quote && <p className="mt-2 text-xs text-darkBlue/60">Tarifs mensuels Twilio : {quote.prices.map((price) => `${price.type} ${price.amount} ${quote.currency}`).join(" · ") || "indisponibles"}. Bundle : {quote.bundle?.status || "non vérifié"}. Des conditions et frais supplémentaires peuvent s’appliquer.</p>}
        {numbers && <ul className="mt-2">{numbers.length ? numbers.map((number) => {
          const local = quote?.prices?.find((price) => price.type === "local");
          const national = quote?.prices?.find((price) => price.type === "national");
          const requirement = number.addressRequirements;
          const candidates = (addresses || []).filter(a => a.validated === true && a.isoCountry && (requirement !== "local" || a.isoCountry === "FR") && (requirement !== "foreign" || a.isoCountry !== "FR"));
          const selectedAddress = candidates.length === 1 ? candidates[0].sid : candidates.some(a => a.sid === addressSid) ? addressSid : "";
          const addressReady = requirement === "none" || ["any", "local", "foreign"].includes(requirement) && Boolean(selectedAddress);
          const purchasable = number.numberType === "local" && !data.draft.phoneNumberSid && !["pending", "uncertain"].includes(data.draft.numberOperation) && quote?.bundle?.status === "twilio-approved" && quote?.bundle?.compatible === true && addressReady && local?.amount != null && national?.amount != null && String(local.amount) === String(national.amount);
          return <li key={number.phoneNumber} className="mt-2 flex flex-wrap items-center gap-2"><span>{number.phoneNumber} {number.locality || ""} · {number.numberType === "local" ? "Local" : number.numberType === "national" ? "National — incompatible avec ce dossier local" : "Type non identifié — achat indisponible"}</span>
            {requirement !== "none" && (!addresses ? <span className="text-red">Vérification des adresses indisponible ; actualisez la recherche.</span> : !candidates.length ? <span className="text-red">Aucune adresse validée compatible avec le pays requis ; achat bloqué.</span> : candidates.length > 1 ? <label>Adresse de l’utilisateur final<select className={field} value={selectedAddress} onChange={(event) => setAddressSid(event.target.value)}><option value="">Sélectionner une adresse</option>{candidates.map(a => <option key={a.sid} value={a.sid}>{[a.customerName, a.street, a.postalCode, a.city, a.isoCountry].filter(Boolean).join(" · ")}</option>)}</select></label> : null)}
            {purchasable && <button type="button" className={button} disabled={busy} onClick={() => requestConfirmation(`Acheter ${number.phoneNumber} auprès de Twilio pour ${local.amount} ${quote.currency} par mois ? Des frais supplémentaires peuvent s’appliquer. Après l’achat, Gusto vérifiera les ressources et pourra créer le domaine et les identifiants SIP, publier une Function de secours Twilio, puis configurer les webhooks si le secours a été testé. Twilio Functions peut entraîner des frais selon l’utilisation, sans abonnement fixe supplémentaire demandé par Gusto.`, () => action(async () => { const response = await axios.post(`${base}/number-purchase`, { phoneNumber: number.phoneNumber, numberType: "local", amount: String(local.amount), currency: quote.currency, addressSid: selectedAddress, confirm: true, technicalConfirm: true, functionConfirm: true }, getAdminAuthConfig()); setTechnical(response.data.technical || null); const result = await axios.get(`${base}/resources`, getAdminAuthConfig()).catch(() => null); if (result) setResources(result.data); }))}>Acheter</button>}
          </li>;
        }) : <li>Aucun numéro disponible.</li>}</ul>}
        <p className="mt-2 text-xs text-darkBlue/60">L’achat est proposé uniquement si le tarif local et national est identique et si le Bundle est approuvé. Twilio vérifie les éventuelles exigences géographiques locales lors de l’achat.</p>
      </div>}
      {!draft?.accountSid && !data.liveExists && <p className="text-sm text-darkBlue/60">Associez d’abord un sous-compte à l’étape 2.</p>}
      </div>
      <div className={step === 4 ? "flex flex-col gap-4" : "hidden"}>
      {draft?.phoneNumberSid && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Configuration technique</p><p role="status" className="mt-1">{busy ? "Opération en cours…" : automation?.message || technical?.message || (draft.webhookOperation === "completed" ? "Configuration enregistrée ; vérification disponible." : "Action nécessaire pour finaliser la configuration.")}</p>{automation?.status !== "running" && draft.fallbackFunction?.operation !== "pending" && <button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => requestConfirmation("Finaliser la configuration technique peut créer un domaine et des identifiants SIP, publier une Function de secours Twilio et modifier les webhooks lorsque le secours est testé. Twilio Functions peut entraîner des frais selon l’utilisation, sans abonnement fixe supplémentaire demandé par Gusto.", () => action(async () => { const response = await axios.post(`${base}/technical-finalize`, { confirm: true, functionConfirm: true }, getAdminAuthConfig()); setTechnical(response.data); const result = await axios.get(`${base}/resources`, getAdminAuthConfig()).catch(() => null); if (result) setResources(result.data); }))}>Finaliser la configuration technique</button>}</div>}
      {data.draft?.accountSid && !data.liveExists && <div><button type="button" className={button} disabled={busy} onClick={() => action(async () => { const response = await axios.get(`${base}/resources`, getAdminAuthConfig()); setResources(response.data); })}>Consulter les ressources du sous-compte</button>{resources && <div className="mt-2 text-sm"><p>Conformité : {resources.bundle?.status || "non vérifiée"}</p><p>Numéros : {resources.numbers.map((item) => item.phoneNumber).join(", ") || "aucun"}</p><p>Domaines SIP : {resources.domains.map((item) => `${item.domainName} (registration ${item.sipRegistration ? "activée" : "désactivée"})`).join(", ") || "aucun"}</p></div>}</div>}
      {data.draft?.accountSid && !data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Domaine SIP : {data.draft.sipDomain || "non configuré"}</p><p className="mt-1 text-darkBlue/60">État : {data.draft.domainOperation || "non commencé"}</p>{["pending", "uncertain"].includes(data.draft.domainOperation) && <p className="mt-2 text-red">Opération en cours ou résultat incertain : vérifiez le domaine dans Twilio avant toute reprise.</p>}{!data.draft.sipDomain && <button type="button" className={`${button} mt-3`} disabled={busy || ["pending", "uncertain"].includes(data.draft.domainOperation)} onClick={() => { requestConfirmation("Créer un domaine SIP avec SIP Registration sur ce sous-compte Twilio ?", () =>  action(() => axios.post(`${base}/domain`, { confirm: true }, getAdminAuthConfig()))); }}>Créer le domaine SIP</button>}<p className="mt-2 text-xs text-darkBlue/60">La création du domaine ne configure pas encore ses identifiants ni le terminal.</p></div>}
      {data.draft?.accountSid && !data.liveExists && !data.draft.sipDomain && <div className="text-sm"><input className={field} value={domainSid} onChange={(event) => setDomainSid(event.target.value)} placeholder="SID d’un domaine SIP existant" /><button type="button" className={`${button} mt-2`} disabled={busy || !domainSid} onClick={() => { requestConfirmation("Associer ce domaine SIP existant à ce restaurant ?", () =>  action(() => axios.post(`${base}/domain-associate`, { sid: domainSid.trim(), confirm: true }, getAdminAuthConfig()))); }}>Associer le domaine</button></div>}
      {data.draft?.sipDomain && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Identifiants SIP</p><p className="mt-1">État : {data.draft.sipCredentialOperation || "non commencé"} · Identifiant : {data.draft.sipUsername || "à créer"}</p>
        {!["completed", "pending", "uncertain"].includes(data.draft.sipCredentialOperation) && <><input className={`${field} mt-2`} value={credentialListSid} onChange={(event) => setCredentialListSid(event.target.value)} placeholder="Credential List SID existante (facultatif)" /><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { requestConfirmation("Créer les identifiants SIP de ce restaurant dans Twilio ?", () =>  action(() => axios.post(`${base}/sip-credentials`, { confirm: true, credentialListSid: credentialListSid.trim() || undefined }, getAdminAuthConfig()))); }}>Créer les identifiants</button></>}
        {data.draft.sipCredentialOperation === "completed" && <div className="mt-2 flex flex-wrap gap-2">{!sipSecret && <button type="button" className={button} disabled={busy} onClick={() => requestConfirmation("Afficher le mot de passe SIP de cet établissement ?", () => action(async () => { const epoch = sipRequestEpoch.current; const result = await axios.post(`${base}/sip-secret`, { confirm: true }, getAdminAuthConfig({ headers: { "Cache-Control": "no-store" } })); if (sipRequestEpoch.current === epoch) { setSipSecret(result.data); setSipCopyStatus(""); } }))}>Afficher</button>}<button type="button" className={button} disabled={busy} onClick={() => requestConfirmation("Changer le mot de passe SIP ? Le terminal devra être reconfiguré.", () => action(async () => { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); await axios.post(`${base}/sip-rotate`, { confirm: true }, getAdminAuthConfig()); }))}>Changer le mot de passe</button></div>}
        {data.draft.sipCredentialOperation === "uncertain" && <p className="mt-2 text-red">Opération SIP incertaine : vérifiez les ressources avant reprise.</p>}
        {data.draft.sipCredentialOperation === "uncertain" && <button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { requestConfirmation("Rapprocher les ressources SIP et réappliquer le mot de passe préparé ? Si vous avez autorisé la reprise après vérification d’absence, les ressources manquantes seront créées.", () =>  action(() => axios.post(`${base}/sip-reconcile`, { confirm: true }, getAdminAuthConfig()))); }}>Rapprocher les identifiants</button>}
        {data.draft.sipCredentialOperation === "uncertain" && data.draft.sipCredentialSid && <button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { requestConfirmation("Reprendre la rotation SIP avec le mot de passe déjà préparé ?", () =>  action(() => axios.post(`${base}/sip-rotation-recover`, { confirm: true }, getAdminAuthConfig()))); }}>Reprendre la rotation</button>}
        {sipSecret && <div className="mt-3 rounded-xl bg-blue/10 p-3"><p>Domaine : {sipSecret.domain}</p><p>Identifiant : {sipSecret.username}</p><p>Mot de passe : <code>{sipSecret.password}</code></p><p className="mt-1 text-xs">Masqué automatiquement après une minute.</p><div className="mt-2 flex flex-wrap gap-2"><button type="button" className={button} onClick={() => { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); }}>Masquer</button><button type="button" className={button} onClick={async () => { try { if (!navigator.clipboard?.writeText) throw new Error("clipboard unavailable"); await navigator.clipboard.writeText(sipSecret.password); setSipCopyStatus("Mot de passe copié."); } catch (_) { setSipCopyStatus("Copie indisponible ; sélectionnez le mot de passe manuellement."); } }}>Copier</button></div>{sipCopyStatus && <p role="status" className="mt-1">{sipCopyStatus}</p>}</div>}
      </div>}
      {data.draft?.sipCredentialOperation === "completed" && data.draft?.phoneNumberSid && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Webhooks et secours</p><p>État : {data.draft.webhookOperation || "non commencé"}</p>{data.draft.fallbackFunction?.operation === "completed" ? <p className="mt-2" role="status">Function de secours publiée et réponse vérifiée. Configurez le terminal, puis testez un appel réel sur un numéro distinct avant de confirmer. Le secours reste à valider en conditions de panne.</p> : <details className="mt-2"><summary>Alternative : TwiML Bin manuel</summary><ol className="mt-2 list-decimal space-y-1 pl-5"><li>Dans la console Twilio du sous-compte, ouvrir Developer tools → TwiML Bins et créer un Bin.</li><li>Copier le TwiML ci-dessous dans le Bin, l’enregistrer puis copier son URL.</li><li>Vérifier sa réponse. Sur un numéro Twilio de test distinct, configurer temporairement ce Bin comme webhook Voice, appeler ce numéro et vérifier la sonnerie, le numéro appelant et l’audio.</li><li>Confirmer le test téléphonique réel, puis configurer le webhook du numéro attribué.</li></ol></details>}<button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const result = await axios.get(`${base}/fallback-template`, getAdminAuthConfig()); setFallbackTemplate(result.data); })}>Afficher le TwiML du restaurant</button>{fallbackTemplate && <pre className="mt-2 overflow-x-auto whitespace-pre-wrap rounded-xl bg-darkBlue/5 p-3 text-xs">{fallbackTemplate.twiml}</pre>}<label className="mt-2 block">URL du secours Twilio<input className={`${field} mt-1`} value={fallbackUrl} onChange={(event) => setFallbackUrl(event.target.value)} placeholder="https://handler.twilio.com/twiml/EH…" /></label><p className="mt-1 text-xs text-darkBlue/60">Le secours est hébergé par Twilio, indépendamment de Gusto. Tant que la route de test n’est pas activée, les appels en dépendent.</p><div className="mt-2 flex flex-wrap gap-2"><button type="button" className={button} disabled={busy || !fallbackUrl} onClick={() => action(() => axios.post(`${base}/fallback-probe`, { fallbackUrl: fallbackUrl.trim() }, getAdminAuthConfig()))}>Vérifier la réponse TwiML</button><button type="button" className={button} disabled={busy || !fallbackUrl || data.draft.fallbackProbeUrl !== fallbackUrl.trim() || !data.draft.fallbackProbeAt} onClick={() => { requestConfirmation(`Confirmer qu’un appel réel via ${fallbackUrl} a été testé pour ce restaurant ? Gusto finalisera ensuite les webhooks si les prérequis sont valides.`, () => action(async () => { await axios.post(`${base}/fallback-verification`, { fallbackUrl: fallbackUrl.trim(), confirm: true }, getAdminAuthConfig()); try { const result = await axios.post(`${base}/technical-finalize`, { confirm: true, functionConfirm: true }, getAdminAuthConfig()); setTechnical(result.data); } catch (_) { setTechnical({ status: "action_required", message: "Secours déclaré ; finalisation des webhooks à vérifier." }); } })); }}>Confirmer le test téléphonique</button><button type="button" className={button} disabled={busy || !fallbackUrl || data.draft.webhookOperation === "pending" || data.draft.verifiedFallbackUrl !== fallbackUrl.trim() || !data.draft.checklist?.fallbackTest} onClick={() => { requestConfirmation("Modifier le webhook du numéro Twilio ? Vérifiez le secours avant de confirmer.", () =>  action(() => axios.post(`${base}/webhooks`, { fallbackUrl: fallbackUrl.trim(), confirm: true }, getAdminAuthConfig()))); }}>Configurer et vérifier les webhooks</button></div></div>}
      {!draft?.accountSid && !data.liveExists && <p className="text-sm text-darkBlue/60">Associez d’abord un sous-compte à l’étape 2.</p>}
      </div>
      <div className={step === 6 ? "flex flex-col gap-4" : "hidden"}>
      {data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Comparer les appels avec Twilio</p><p className="mt-1 text-xs text-darkBlue/60">Cette vérification en lecture seule signale les appels de la période absents de Gusto, notamment après une panne. La récupération ne transmet aucune minute à Stripe.</p><div className="mt-2 flex flex-wrap gap-2"><label>Début UTC <input type="date" value={twilioStart} onChange={(event) => setTwilioStart(event.target.value)} /></label><label>Fin UTC exclusive <input type="date" value={twilioEnd} onChange={(event) => setTwilioEnd(event.target.value)} /></label></div><button type="button" className={`${button} mt-2`} disabled={busy || Boolean(twilioStart) !== Boolean(twilioEnd)} onClick={() => action(async () => { const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/twilio-reconciliation`, { ...getAdminAuthConfig(), params: twilioStart && twilioEnd ? { start: `${twilioStart}T00:00:00Z`, end: `${twilioEnd}T00:00:00Z` } : {} }); setTwilioInventory(result.data); })}>Vérifier les appels Twilio</button>{twilioInventory && <div className="mt-2"><p>{twilioInventory.observed} appel(s) observé(s) · {twilioInventory.missingCount} absent(s) de l’historique Gusto.</p>{!twilioInventory.complete && <p>Résultat partiel : plus de 10 000 appels à vérifier.</p>}{twilioInventory.missingTruncated && <p>Seuls les 50 premiers appels absents sont affichés ; réduisez la période pour consulter les autres.</p>}{twilioInventory.missing.map((call) => <div key={call.sid} className="mt-2"><p>{new Date(call.startedAt).toLocaleString("fr-FR")} · {call.sid} · {call.status}</p>{call.status === "completed" && <button type="button" className={`${button} mt-1`} disabled={busy} onClick={() => { requestConfirmation("Après vérification de l’appel dans Twilio, saisissez JE CONFIRME RECUPERATION APPEL. Cette récupération ne transmettra aucune minute à Stripe.", (acknowledgement) => action(async () => { await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/recover-twilio-call`, { callSid: call.sid, acknowledgement }, getAdminAuthConfig()); const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/twilio-reconciliation`, { ...getAdminAuthConfig(), params: twilioStart && twilioEnd ? { start: `${twilioStart}T00:00:00Z`, end: `${twilioEnd}T00:00:00Z` } : {} }); setTwilioInventory(result.data); }), { phrase: "JE CONFIRME RECUPERATION APPEL" }); }}>Récupérer après vérification</button>}</div>)}<p className="text-xs text-darkBlue/60">Un appel absent ne prouve pas une conversation facturable. Vérifiez ses détails avant toute régularisation.</p></div>}</div>}
      <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Vérification des opérations d’abonnement</p><p className="mt-1 text-xs text-darkBlue/60">Si une opération est restée en attente, vérifiez Stripe et assurez-vous qu’aucun autre serveur ne la traite avant de la débloquer.</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/subscription-recovery`, getAdminAuthConfig()); setSubscriptionRecovery(result.data); })}>Vérifier l’opération Stripe</button>{subscriptionRecovery && (subscriptionRecovery.pending ? <div className="mt-2"><p className="font-semibold">Opération d’abonnement à vérifier</p><p>État : {subscriptionRecovery.state} · depuis {new Date(subscriptionRecovery.startedAt).toLocaleString("fr-FR")}</p><p>{subscriptionRecovery.subscription ? `Abonnement trouvé : ${subscriptionRecovery.subscription.id} (${subscriptionRecovery.subscription.status}).` : "Aucun abonnement trouvé : vérifier également le tableau de bord Stripe avant de confirmer."}</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { const phrase = subscriptionRecovery.subscription ? "JE CONFIRME LA VERIFICATION STRIPE" : "JE CONFIRME ABSENCE STRIPE"; requestConfirmation(`Après vérification, saisissez ${phrase}. Aucun abonnement ne sera créé automatiquement.`, (acknowledgement) => action(async () => { await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/subscription-recovery`, { acknowledgement }, getAdminAuthConfig()); setSubscriptionRecovery(null); }), { phrase: phrase }); }}>Débloquer après vérification</button></div> : <p className="mt-2">Aucune opération interrompue.</p>)}</div>
      {data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Consommation de la période Stripe</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const response = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/usage`, getAdminAuthConfig()); setUsage(response.data.usage); })}>Consulter la consommation</button>{usage && (!usage.available ? <div className="mt-2"><p>Offre ou abonnement incomplet : période courante indisponible.</p>{usage.history?.map((period, index) => <p key={`${period.periodStart}-${period.periodEnd}-${index}`}>{new Date(period.periodStart).toLocaleDateString("fr-FR")} – {new Date(period.periodEnd).toLocaleDateString("fr-FR")} : {period.verifiedMinutes} min vérifiées, {period.reportedMinutes} min transmises</p>)}</div> : <div className="mt-2"><p>Estimation : {usage.usedMinutes} / {usage.includedMinutes} minutes · dépassement : {usage.overageMinutes} min</p><p>Reçus : {usage.received} · répondus : {usage.answered} · manqués ou occupés : {usage.missed}</p><p>Fin de période : {new Date(usage.periodEnd).toLocaleDateString("fr-FR")}</p><p>Minutes vérifiées : {usage.verifiedMinutes} · transmises : {usage.reportedMinutes}</p>{usage.history?.length > 0 && <div className="mt-2"><p className="font-semibold">Périodes enregistrées</p>{usage.history.map((period, index) => <p key={`${period.periodStart}-${period.periodEnd}-${index}`}>{new Date(period.periodStart).toLocaleDateString("fr-FR")} – {new Date(period.periodEnd).toLocaleDateString("fr-FR")} : {period.verifiedMinutes} min vérifiées, {period.reportedMinutes} min transmises{period.pending ? ` · ${period.pending} à vérifier` : ""}</p>)}</div>}<p className="text-xs text-darkBlue/60">Estimation non rapprochée de la facture Stripe.</p></div>)}</div>}
      {data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Transmission des minutes à Stripe</p><p className="mt-1 text-xs text-darkBlue/60">Activation distincte du service téléphonique, réservée à un administrateur après validation de la recette. Les appels antérieurs à l’activation ne sont pas transmis.</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, getAdminAuthConfig()); setMetering(result.data); })}>Consulter l’état des envois</button>{metering && <div className="mt-2"><p>{metering.enabled ? "Envois activés pour ce restaurant" : "Envois désactivés pour ce restaurant"} · serveur : {metering.globalEnabled ? "autorisé" : "désactivé"}</p><p>Consommations à vérifier ou transmettre : {metering.outstanding}</p>{metering.reconciliation?.error && <p className="mt-2">Rapprochement interrompu : {metering.reconciliation.error}. Le traitement reprendra automatiquement.</p>}{metering.reconciliation?.anomalies?.length > 0 && <div className="mt-2"><p className="font-semibold">Appels Twilio à vérifier</p>{metering.reconciliation.anomalies.map((item) => <div className="mt-1 text-xs" key={item.callSid}><p>{new Date(item.startedAt).toLocaleString("fr-FR")} · {item.callSid} · {item.reason}</p><button type="button" className={`${button} mt-1`} disabled={busy} onClick={() => { requestConfirmation("Après vérification de cet appel, saisissez JE CONFIRME LA VERIFICATION pour retirer l’anomalie. Aucun appel ne sera modifié.", (acknowledgement) => action(async () => { await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/reconciliation/anomalies/${item.callSid}/dismiss`, { acknowledgement }, getAdminAuthConfig()); const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, getAdminAuthConfig()); setMetering(result.data); }), { phrase: "JE CONFIRME LA VERIFICATION" }); }}>Classer après vérification</button></div>)}<p className="text-xs text-darkBlue/60">Utilisez la comparaison Twilio ci-dessus pour examiner ces appels.</p></div>}{metering.manualAdjustments?.length > 0 && <div className="mt-2"><p className="font-semibold">Régularisations manuelles à traiter</p>{metering.manualAdjustments.map((item) => <p key={item.identifier} className="text-xs">{item.parentSid} · {item.minutes} min · période {item.periodStart && item.periodEnd ? `${new Date(item.periodStart).toLocaleDateString("fr-FR")} – ${new Date(item.periodEnd).toLocaleDateString("fr-FR")}` : "d’origine inconnue — à déterminer"} · événement {item.identifier}</p>)}<p className="text-xs text-darkBlue/60">Vérifiez la facture et l’événement avant toute opération manuelle. Aucune facture n’a été modifiée.</p></div>}<button type="button" className={`${button} mt-2`} disabled={busy || (!metering.enabled && !metering.globalEnabled)} onClick={() => { const enabled = !metering.enabled; const phrase = enabled ? "JE CONFIRME LA RECETTE" : "JE SUSPENDS LES ENVOIS"; requestConfirmation(`Saisissez ${phrase} pour ${enabled ? "autoriser les envois futurs" : "suspendre les envois futurs"}. Une requête déjà en cours peut aboutir.`, (acknowledgement) => action(async () => { await axios.put(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, { enabled, acknowledgement }, getAdminAuthConfig()); const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, getAdminAuthConfig()); setMetering(result.data); }), { phrase: phrase }); }}>{metering.enabled ? "Suspendre les envois" : "Activer après recette"}</button></div>}</div>}
      {data.liveExists && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Rapprochement Stripe</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/reconciliation`, getAdminAuthConfig()); setReconciliation(result.data); })}>Comparer les minutes</button>{reconciliation && (reconciliation.available ? <div className="mt-2"><p>Du {new Date(reconciliation.from).toLocaleString("fr-FR")} au {new Date(reconciliation.until).toLocaleString("fr-FR")} : {reconciliation.reportedMinutes} min transmises, {reconciliation.stripeMinutes} min agrégées par Stripe.</p><p>{reconciliation.matches ? "Valeurs concordantes sur cet intervalle." : "Écart à vérifier ; Stripe peut traiter les événements avec retard."} {reconciliation.pending} entrée(s) en attente.</p><p className="text-xs text-darkBlue/60">La comparaison exclut les minutes partielles aux limites de l’intervalle et ne valide pas la facture.</p></div> : <p className="mt-2">Période trop courte pour une comparaison.</p>)}{metering?.reviewCalls?.length > 0 && <div className="mt-2"><p className="font-semibold">Appels nécessitant une vérification</p>{metering.reviewCalls.map((call) => <div key={call._id} className="mt-2"><p>{new Date(call.createdAt).toLocaleString("fr-FR")} · {call.callSid} · {call.billingReviewReason || "envoi incertain"}</p>{call.entry && <p className="text-xs">Événement : {call.entry.identifier} · {call.entry.minutes} min · {call.entry.lastError}</p>}{call.entry?.state === "review" && <div className="mt-1 flex flex-wrap gap-2">{[["excluded", "Classer sans facturer"], ["manual", "Préparer une régularisation manuelle"]].map(([resolution, label]) => <button key={resolution} type="button" className={button} disabled={busy} onClick={() => { requestConfirmation("Vérifiez d’abord l’événement et la facture Stripe. Cette action ne renvoie rien et ne crée aucune facture. Saisissez JE CONFIRME LA VERIFICATION.", (acknowledgement) => action(async () => { await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/${call._id}/resolve`, { resolution, acknowledgement }, getAdminAuthConfig()); const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, getAdminAuthConfig()); setMetering(result.data); }), { phrase: "JE CONFIRME LA VERIFICATION" }); }}>{label}</button>)}</div>}{["delai_idempotence_depasse", "confirme_par_administrateur"].includes(call.entry?.lastError) && <button type="button" className={`${button} mt-1`} disabled={busy} onClick={() => { requestConfirmation("Après vérification de cet événement dans Stripe, saisissez JE CONFIRME EVENEMENT STRIPE. Aucun événement ne sera renvoyé.", (acknowledgement) => action(async () => { await axios.post(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering/${call._id}/confirm-reported`, { acknowledgement }, getAdminAuthConfig()); const result = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/admin/restaurants/${restaurantId}/callsense/metering`, getAdminAuthConfig()); setMetering(result.data); }), { phrase: "JE CONFIRME EVENEMENT STRIPE" }); }}>Confirmer l’événement reçu</button>}</div>)}</div>}</div>}
      {data.draft && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Checklist de recette</p><p className="mt-1 text-xs text-darkBlue/60">Cochez uniquement les vérifications réellement effectuées. La checklist ne déclenche pas l’activation.</p><div className="mt-3 flex flex-col gap-2">{Object.entries(checklistLabels).map(([key, label]) => <label key={key} className="flex items-center gap-2"><input type="checkbox" disabled={busy} checked={Boolean(checklist[key])} onChange={(event) => setChecklist((current) => ({ ...current, [key]: event.target.checked }))} />{label}</label>)}</div><button type="button" className={`${button} mt-3`} disabled={busy} onClick={() => action(() => axios.put(`${base}/checklist`, { checklist: Object.fromEntries(Object.keys(checklistLabels).map((key) => [key, Boolean(checklist[key])])) }, getAdminAuthConfig()))}>Enregistrer la checklist</button></div>}
      {data.draft && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">État technique : {statusLabels[data.draft.serviceStatus] || "Préparation"}</p><p className="mt-1 text-xs text-darkBlue/60">Le mode prêt à tester ouvre la route téléphonique de test. L’activation définitive exige tous les tests déclarés et une nouvelle vérification Twilio.</p><div className="mt-2 flex flex-wrap gap-2">{[["ready_for_test", "Prêt à tester"], ["active", "Activer après recette"], ["hardware_pending", "Attente matériel"], ["compliance_pending", "Attente conformité"], ["incident", "Incident"], ["suspended", "Suspendre"], ["preparing", "Préparation"]].map(([status, label]) => <button key={status} type="button" className={button} disabled={busy || status === data.draft.serviceStatus} onClick={() => { requestConfirmation(`Passer le service à l’état « ${label} » ?`, () =>  action(() => axios.post(`${base}/status`, { status, confirm: true }, getAdminAuthConfig()))); }}>{label}</button>)}</div></div>}
      {data.draft && (!data.liveExists || data.liveManaged) && (() => {
        const operations = [["account", "Sous-compte", data.draft.accountOperation], ["number", "Numéro", data.draft.numberOperation], ["domain", "Domaine SIP", data.draft.domainOperation], ["sip", "Identifiants SIP", data.draft.sipCredentialOperation], ["webhook", "Webhooks", data.draft.webhookOperation], ["activation", "Activation", data.draft.activationOperation]].filter((item) => ["pending", "uncertain"].includes(item[2]));
        if (!operations.length) return null;
        const unlock = (resetAbsent) => {
          const phrase = resetAbsent ? "JE CONFIRME ABSENCE ET ARRET" : "JE CONFIRME LA VERIFICATION";
          requestConfirmation(`Vérifiez qu’aucun ancien serveur ne traite encore cette opération. Aucun achat ou création ne sera relancé automatiquement.`, (acknowledgement) => action(async () => { await axios.post(`${base}/recovery-unlock`, { operation: recoveryResult.operation, inspectionId: recoveryResult.id, acknowledgement, resetAbsent }, getAdminAuthConfig()); setRecoveryResult(null); }), { phrase });
        };
        return <div className="rounded-xl border border-orange-300 bg-orange-50 p-3 text-sm"><p className="font-semibold">Reprise après interruption</p><p className="mt-1">Une vérification consulte Twilio sans modifier de ressource. Attendez au moins deux minutes après une opération en cours et vérifiez qu’aucun ancien serveur ne l’exécute encore.</p><div className="mt-2 flex flex-wrap gap-2">{operations.map(([key, label, state]) => <button key={key} type="button" className={button} disabled={busy} onClick={() => action(async () => { const result = await axios.post(`${base}/recovery-inspect`, { operation: key }, getAdminAuthConfig()); setRecoveryResult(result.data); })}>Vérifier {label} ({state === "pending" ? "en cours" : "incertain"})</button>)}</div>{recoveryResult && <div className="mt-3"><p>Résultat : {recoveryLabels[recoveryResult.evidence] || "Inconnu"} · {new Date(recoveryResult.checkedAt).toLocaleString("fr-FR")}</p>{recoveryResult.startedAt && <p>Début de l’opération : {new Date(recoveryResult.startedAt).toLocaleString("fr-FR")}</p>}<p className="mt-1">{recoveryResult.notice}</p>{recoveryResult.resources?.length > 0 && <ul className="mt-2 list-disc pl-5">{recoveryResult.resources.map((item, index) => <li key={`${item.sid || item.status}-${index}`}><code>{item.sid || ""}</code> {item.name || item.phoneNumber || item.status || ""} {item.credentials?.map((credential) => <span key={credential.sid}> · identifiant {credential.username} ({credential.sid})</span>)} {item.sid && ["account", "number", "domain"].includes(recoveryResult.operation) && <button type="button" className="text-blue underline" onClick={() => { if (recoveryResult.operation === "account") setAccountSid(item.sid); if (recoveryResult.operation === "number") setNumberSid(item.sid); if (recoveryResult.operation === "domain") setDomainSid(item.sid); }}>Utiliser ce SID</button>}</li>)}</ul>}<div className="mt-2 flex flex-wrap gap-2"><button type="button" className={button} disabled={busy} onClick={() => unlock(false)}>Débloquer pour rapprochement</button>{(recoveryResult.evidence === "absent" || recoveryResult.evidence === "partial" && recoveryResult.operation === "sip") && ["account", "number", "domain", "sip"].includes(recoveryResult.operation) && <button type="button" className={button} disabled={busy} onClick={() => unlock(true)}>Confirmer l’absence et permettre une nouvelle tentative</button>}</div><p className="mt-1 text-xs">La nouvelle création ou le nouvel achat nécessite ensuite une confirmation séparée. Une liste vide ne garantit pas qu’une ancienne requête ne puisse plus aboutir.</p></div>}</div>;
      })()}
      {data.draft?.audit?.length > 0 && <details className="text-sm"><summary className="cursor-pointer font-semibold">Journal des opérations</summary><ul className="mt-2 space-y-1">{data.draft.audit.slice().reverse().map((entry, index) => <li key={`${entry.at}-${index}`}>{entry.at ? new Date(entry.at).toLocaleString("fr-FR") : "Date inconnue"} · {entry.action} · administrateur {entry.actorId || "inconnu"}{entry.details ? ` · ${entry.details}` : ""}</li>)}</ul></details>}
      <div className="rounded-xl bg-darkBlue/5 p-3 text-sm"><p className="font-semibold">Validation</p><p>La conformité est vérifiée auprès de Twilio. Le secours, le renvoi et les essais téléphoniques doivent être vérifiés par un administrateur.</p></div>
      </div>
      <div className={step === 5 ? "flex flex-col gap-4" : "hidden"}>
      {terminalType === "HT813" && <div className="rounded-xl bg-darkBlue/5 p-3 text-sm"><p className="font-semibold">Fiche installateur HT813 — à tester</p><p>Domaine SIP : {data.draft?.sipDomain || "à configurer"} · SIP User ID et Authenticate ID : {data.draft?.sipUsername || "à configurer"}. Destination : {data.draft?.sipUsername && data.draft?.sipDomain ? `sip:${data.draft.sipUsername}@${data.draft.sipDomain}` : "à configurer"}. Le mot de passe est affiché séparément à l’administrateur autorisé.</p><p>Relier le port WAN Ethernet au réseau, FXS à la base téléphonique et FXO à la sortie analogique de la box. Les entrants suivent Twilio puis SIP vers FXS ; préparer le dial plan FXS vers FXO pour les sortants via l’opérateur historique.</p><p>Tester les codecs G.711 PCMU et PCMA, les réglages NAT et l’inscription SIP. Vérifier sonnerie, audio bidirectionnel et Caller ID. Tester les règles de numérotation et la procédure d’urgence avec l’opérateur ; ne pas présumer du routage FXO.</p><p>Tester pannes Internet et électriques. Pour revenir en arrière, désactiver le renvoi opérateur et rétablir le branchement téléphonique d’origine. Le mode lifeline seul ne suffit pas si le renvoi reste actif. Aucun test matériel n’a été réalisé.</p></div>}
      <p className="text-sm text-darkBlue/60">Le renvoi du numéro public vers le numéro Twilio est configuré auprès de l’opérateur. Vérifier la conservation du numéro appelant et les frais éventuels.</p>
      </div>
    </div>}
    {confirmation && <div className="fixed inset-0 z-[220] flex items-end justify-center bg-black/40 tablet:items-center tablet:p-6">
      <div role="dialog" aria-modal="true" aria-labelledby="callsense-confirm-title" aria-describedby="callsense-confirm-description" className="w-full max-w-lg rounded-t-3xl bg-white p-5 shadow-xl tablet:rounded-2xl tablet:p-6" onKeyDown={(event) => {
        if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); closeConfirmation(); }
        if (event.key === "Tab") {
          const controls = Array.from(event.currentTarget.querySelectorAll('button:not(:disabled), [href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])'));
          if (!controls.length) { event.preventDefault(); return; }
          if (event.shiftKey && document.activeElement === controls[0]) { event.preventDefault(); controls[controls.length - 1].focus(); }
          else if (!event.shiftKey && document.activeElement === controls[controls.length - 1]) { event.preventDefault(); controls[0].focus(); }
        }
      }}>
        <div className="flex items-start justify-between gap-4"><h3 id="callsense-confirm-title" className="text-lg font-semibold">{confirmation.title || "Confirmer l’opération"}</h3><button type="button" aria-label="Fermer la confirmation" disabled={busy} onClick={closeConfirmation} className="rounded-xl border border-darkBlue/10 px-3 py-1 text-lg disabled:opacity-50">×</button></div>
        <p className="mt-3 text-sm"><strong>Établissement :</strong> {data?.restaurant?.name || "Non renseigné"}</p>
        <p id="callsense-confirm-description" className="mt-3 text-sm">{confirmation.text}</p>
        {confirmation.phrase && <label className="mt-4 block text-sm font-semibold">Saisissez <span className="break-words">{confirmation.phrase}</span><input className={`${field} mt-1`} value={acknowledgement} disabled={busy} onChange={(event) => setAcknowledgement(event.target.value)} autoComplete="off" /></label>}
        {confirmationError && <p role="alert" className="mt-3 rounded-xl bg-red/10 p-3 text-sm text-red">{confirmationError}</p>}
        <div className="mt-5 flex flex-col-reverse gap-2 tablet:flex-row tablet:justify-end"><button type="button" autoFocus disabled={busy} onClick={closeConfirmation} className="rounded-xl border border-darkBlue/10 bg-white px-4 py-2 text-sm font-semibold disabled:opacity-50">Annuler</button><button type="button" disabled={busy || Boolean(confirmationError) || Boolean(confirmation.phrase && acknowledgement !== confirmation.phrase)} onClick={confirmAction} className={button}>{busy ? <span role="status">Opération en cours…</span> : confirmation.confirmLabel || "Confirmer"}</button></div>
      </div>
    </div>}
  </section>;
}
